// ══════════════════════════════════════════════════
// NORMALISER SOURCE — Drive, Gmail, Batch (v8)
// + Validation alias +scan
// + Passthrough _attachId / _attachIndex / _attachTotal
// ══════════════════════════════════════════════════
const item   = $input.first().json;
const binary = $input.first().binary || {};

// ── Helper: extraire email brut depuis formats variés ──
// "_scanner <debourouba+scan@gmail.com>" → "debourouba+scan@gmail.com"
// "debourouba+scan@gmail.com" → "debourouba+scan@gmail.com"
function extractEmail(raw) {
  if (!raw) return '';
  const angleBracket = raw.match(/<([^>]+)>/);
  if (angleBracket) return angleBracket[1].trim().toLowerCase();
  const plain = raw.match(/([^\s<>"',;]+@[^\s<>"',;]+)/);
  return plain ? plain[1].trim().toLowerCase() : raw.trim().toLowerCase();
}

// ── Validation destinataire alias +scan ──────────────
function isValidScanTarget(headers) {
  if (!headers || !Array.isArray(headers)) return true; // pas de headers = laisser passer
  const SCAN_ALIAS = ($env.GED_GMAIL_ALIAS || 'debourouba+scan@gmail.com').toLowerCase();

  const toHeader        = headers.find(h => (h.name||'').toLowerCase() === 'to');
  const deliveredHeader = headers.find(h => (h.name||'').toLowerCase() === 'delivered-to');
  const ccHeader        = headers.find(h => (h.name||'').toLowerCase() === 'cc');

  const toEmail        = extractEmail(toHeader?.value        || '');
  const deliveredEmail = extractEmail(deliveredHeader?.value || '');
  const ccEmail        = extractEmail(ccHeader?.value        || '');

  // Accepter si l'alias apparaît dans To OU Delivered-To OU CC
  return [toEmail, deliveredEmail, ccEmail].some(e => e.includes(SCAN_ALIAS));
}

// ── BATCH ──────────────────────────────────────────
if (item.source === 'BATCH') {
  return [{ json: {
    source:       'BATCH',
    fileId:       item.fileId   || '',
    gmailId:      '',
    fileName:     item.fileName || 'document.pdf',
    mimeType:     'application/pdf',
    fileUrl:      item.fileUrl  || '',
    empreinte:    '',
    hash:         '',
    _attachId:    null,
    _attachIndex: 1,
    _attachTotal: 1
  }, binary }];
}

// ── GMAIL ──────────────────────────────────────────
const isGmail = !!(item.threadId || item.historyId || Array.isArray(item.labels));

if (isGmail) {
  // Extraire headers depuis payload si disponibles (email complet)
  const headers = item.payload?.headers || null;

  // Validation alias — rejeter silencieusement si pas le bon destinataire
  if (headers && !isValidScanTarget(headers)) {
    console.warn(`Email ignoré — destinataire non reconnu. id=${item.id}`);
    // Retourner item vide qui sera filtré par le nœud suivant
    return [{ json: {
      source:        'GMAIL_IGNORE',
      fileId:        'ignore_' + item.id,
      gmailId:       item.id,
      fileName:      'ignore.pdf',
      mimeType:      'application/pdf',
      fileUrl:       '',
      empreinte:     '',
      hash:          '',
      _attachId:     null,
      _attachIndex:  1,
      _attachTotal:  0,
      _ignored:      true,
      _ignoreReason: 'Destinataire alias non reconnu'
    }}];
  }

  // Extraire from/subject depuis headers si dispo
  let fromAddress = item.from || item.From || '';
  let subject     = item.subject || item.Subject || '';
  if (headers) {
    const hFrom    = headers.find(h => h.name.toLowerCase() === 'from');
    const hSubject = headers.find(h => h.name.toLowerCase() === 'subject');
    if (hFrom)    fromAddress = hFrom.value || fromAddress;
    if (hSubject) subject     = hSubject.value || subject;
  }

  // _attachId/_attachIndex/_attachTotal injectés par 🔍 Compter & Lister PJ
  const attachId    = item._attachId    || null;
  const attachIndex = item._attachIndex || 1;
  const attachTotal = item._attachTotal || 1;
  const fileName    = item.fileName     || `facture_email_${item.id}_${attachIndex}.pdf`;

  return [{ json: {
    source:       'GMAIL',
    fileId:       `gmail_${item.id}_${attachIndex}`,
    gmailId:      item.id,
    fileName:     fileName,
    mimeType:     item.mimeType || 'application/pdf',
    fileUrl:      '',
    empreinte:    '',
    hash:         '',
    emailFrom:    fromAddress,
    emailSubject: subject,
    _attachId:    attachId,
    _attachIndex: attachIndex,
    _attachTotal: attachTotal
  }, binary }];
}

// ── GOOGLE DRIVE — fallback si données manquantes ──
if (!item.id || !item.mimeType) {
  console.warn('Source Drive incomplète — fallback. Keys:', Object.keys(item).join(','));
  return [{ json: {
    source:         'DRIVE',
    fileId:         item.id || 'unknown_' + Date.now(),
    gmailId:        '',
    fileName:       item.name || 'document_inconnu.pdf',
    mimeType:       item.mimeType || 'application/pdf',
    fileUrl:        item.webViewLink || '',
    empreinte:      '',
    hash:           '',
    _attachId:      null,
    _attachIndex:   1,
    _attachTotal:   1,
    _sourceWarning: 'Données Drive incomplètes'
  }, binary }];
}

return [{ json: {
  source:       'DRIVE',
  fileId:       item.id,
  gmailId:      '',
  fileName:     item.name || 'document.pdf',
  mimeType:     item.mimeType,
  fileUrl:      item.webViewLink || '',
  empreinte:    '',
  hash:         '',
  _attachId:    null,
  _attachIndex: 1,
  _attachTotal: 1
}, binary }];

// ══════════════════════════════════════════════════
// NETTOYAGE JSON — Parsing réponse Gemini (v8)
// + famille_document (COMPTABLE / ADMINISTRATIF)
// + est_fiscal_ai (signal IA explicite)
// Robuste : jamais de throw — fallback BASSE confiance si erreur
// ══════════════════════════════════════════════════

const inputItem = $input.first();
const item = inputItem.json;

if (inputItem.binary) {
  delete inputItem.binary;
}

const sourceItem = $('⚙️ Normaliser Source').first().json;
const now = $now.setZone('America/Toronto');

// ── Fallback complet si Gemini échoue ──────────────
function makeFallback(reason) {
  console.warn('PARSER FALLBACK:', reason);
  return [{
    json: {
      // Zone A
      date:                 now.toISODate(),
      emetteur:             'INCONNU',
      type_document:        'ADMIN',
      famille_document:     'ADMINISTRATIF',
      beneficiaire:         'ANONYME',
      objet:                'Document non analysable',
      // Zone B
      categorie:            '',
      sous_categorie:       '',
      confiance:            'BASSE',
      raison_doute:         `Analyse IA échouée : ${reason}`,
      mention_manuscrite:   null,
      // Zone C
      montant_ttc:          0,
      est_financier:        false,
      est_fiscal_ai:        false,
      flag_mixte:           false,
      montant_pro_estime:   null,
      montant_perso_estime: null,
      ratio_pro_pct:        null,
      // Zone E
      _source:      sourceItem.source    || 'INCONNUE',
      _fileName:    sourceItem.fileName  || 'INCONNU',
      _originalUrl: sourceItem.fileUrl   || '',
      _empreinte:   sourceItem.empreinte || '',
      _hash:        sourceItem.hash      || '',
      _gmailId:     sourceItem.gmailId   || '',
      _fileId:      sourceItem.fileId    || 'INCONNU',
      _parseError:  true
    }
  }];
}

// ── Extraire texte brut de la réponse Gemini ───────
const rawText = item?.candidates?.[0]?.content?.parts?.[0]?.text || '';

if (!rawText || rawText.trim() === '') {
  return makeFallback('Réponse Gemini vide ou absente');
}

// ── Extraire bloc JSON ──────────────────────────────
const jsonMatch = rawText.match(/\{[\s\S]*\}/);
if (!jsonMatch) {
  return makeFallback('Aucun JSON trouvé dans la réponse Gemini');
}

// ── Parser JSON ─────────────────────────────────────
let parsed;
try {
  parsed = JSON.parse(jsonMatch[0]);
} catch(e) {
  return makeFallback('JSON malformé : ' + e.message);
}

// ── Date ────────────────────────────────────────────
let dateFinale = now.toISODate();
try {
  const dateInput = parsed.date || '';
  if (dateInput) {
    const dateObj = DateTime.fromISO(dateInput).setZone('America/Toronto');
    if (dateObj.isValid && dateObj.year >= 2000 && dateObj.year <= now.year + 1) {
      dateFinale = dateObj.toISODate();
    }
  }
} catch(e) {
  console.warn('Date parse error:', e.message);
}

// ── Type + Famille + Montant ─────────────────────────
const type = (parsed.type_document || '').toUpperCase() || 'ADMIN';

// famille_document : valider contre les valeurs attendues, fallback logique
const COMPTABLE_TYPES = ['FACTURE', 'RECU', 'RELEVE'];
const rawFamille = (parsed.famille_document || '').toUpperCase();
let familleDoc;
if (rawFamille === 'COMPTABLE') {
  familleDoc = 'COMPTABLE';
} else if (rawFamille === 'ADMINISTRATIF') {
  familleDoc = 'ADMINISTRATIF';
} else {
  // Inférence de sécurité si Gemini n'a pas retourné le champ
  familleDoc = COMPTABLE_TYPES.includes(type) ? 'COMPTABLE' : 'ADMINISTRATIF';
  console.warn(`famille_document absent/invalide (${rawFamille}) — inféré: ${familleDoc}`);
}

let ttc = parseFloat(parsed.montant_ttc) || 0;

// FACTURE/RECU à 0$ → confiance dégradée, pas de throw
let raison_doute = parsed.raison_doute || null;
if (['FACTURE', 'RECU'].includes(type) && ttc === 0) {
  raison_doute = (raison_doute ? raison_doute + ' — ' : '') + 'Montant TTC à 0$ pour ' + type + ' : vérification requise';
}

// ── est_fiscal_ai (signal IA brut) ───────────────────
// Valider la cohérence : ADMINISTRATIF ne peut pas être fiscal
const estFiscalAi = parsed.est_fiscal === true && familleDoc === 'COMPTABLE';

// ── Champs MIXTE ─────────────────────────────────────
const flagMixte = parsed.flag_mixte === true;
const montantProEstime   = flagMixte ? (parseFloat(parsed.montant_pro_estime)   || null) : null;
const montantPersoEstime = flagMixte ? (parseFloat(parsed.montant_perso_estime) || null) : null;
const ratioProPct        = flagMixte ? (parseInt(parsed.ratio_pro_pct)          || null) : null;

// ── Confiance ────────────────────────────────────────
let confiance = (parsed.confiance || 'BASSE').toUpperCase();
if (!['HAUTE','MOYENNE','BASSE'].includes(confiance)) confiance = 'BASSE';
if (flagMixte && montantProEstime === null) confiance = 'BASSE';

// ── Bénéficiaire ─────────────────────────────────────
const beneficiaireFinale = (parsed.beneficiaire && parsed.beneficiaire.trim() !== '')
  ? parsed.beneficiaire.toUpperCase()
  : 'ANONYME';

return [{
  json: {
    // Zone A
    date:                 dateFinale,
    emetteur:             parsed.emetteur     || 'INCONNU',
    type_document:        type,
    famille_document:     familleDoc,
    beneficiaire:         beneficiaireFinale,
    objet:                parsed.objet        || '',
    // Zone B
    categorie:            (parsed.categorie      || '').toUpperCase(),
    sous_categorie:       (parsed.sous_categorie || '').toUpperCase(),
    confiance:            confiance,
    raison_doute:         raison_doute,
    mention_manuscrite:   parsed.mention_manuscrite || null,
    // Zone C
    montant_ttc:          ttc,
    est_financier:        parsed.est_financier !== false,
    est_fiscal_ai:        estFiscalAi,
    flag_mixte:           flagMixte,
    montant_pro_estime:   montantProEstime,
    montant_perso_estime: montantPersoEstime,
    ratio_pro_pct:        ratioProPct,
    // Zone E
    _source:      sourceItem.source    || 'INCONNUE',
    _fileName:    sourceItem.fileName  || 'INCONNU',
    _originalUrl: sourceItem.fileUrl   || '',
    _empreinte:   sourceItem.empreinte || '',
    _hash:        sourceItem.hash      || '',
    _gmailId:     sourceItem.gmailId   || '',
    _fileId:      sourceItem.fileId    || 'INCONNU',
    _parseError:  false
  }
}];

// ══════════════════════════════════════════════════════════════
// NORMALISATION FISCALE + NOMENCLATURE DIFFÉRENCIÉE
// v2: + famille_document + est_fiscal_ai propagés
// ══════════════════════════════════════════════════════════════
const items = $input.all();

return items.map(item => {
  const data = item.json;
  const type = (data.type_document || 'ADMIN').toUpperCase();

  // ── Famille document ───────────────────────────────────────
  const COMPTABLE_TYPES = ['FACTURE', 'RECU', 'RELEVE'];
  const rawFamille = (data.famille_document || '').toUpperCase();
  const famille = rawFamille === 'COMPTABLE' ? 'COMPTABLE'
                : rawFamille === 'ADMINISTRATIF' ? 'ADMINISTRATIF'
                : COMPTABLE_TYPES.includes(type) ? 'COMPTABLE' : 'ADMINISTRATIF';

  // ── Calculs taxes ──────────────────────────────────────────
  const ttc = parseFloat(data.montant_ttc) || 0;

  // ── Helpers ────────────────────────────────────────────────
  function san(str, maxLen = 30) {
    if (!str && str !== 0) return 'INCONNU';
    return String(str).toUpperCase()
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
      .replace(/[^A-Z0-9]/g, '_')
      .replace(/_{2,}/g, '_')
      .replace(/^_+|_+$/g, '')
      .substring(0, maxLen);
  }

  const date    = data.date || new Date().toISOString().split('T')[0];
  const emet    = san(data.emetteur, 25);
  const objet   = san(data.objet || data.sous_categorie, 25);
  const benef   = san(data.beneficiaire, 20);
  const montant = String(Math.round(ttc * 100) / 100).replace('.', '-');

  // ── Nomenclature selon type_document ──────────────────────
  let cleanName = data.clean_filename || '';

  // Reconstruire proprement selon le type (en cas de clean_filename absent ou mal formé)
  const FINANCIAL = ['FACTURE', 'RECU'];
  const isFinancial = FINANCIAL.includes(type) || data.est_financier === true;

  if (!cleanName || cleanName === 'DOCUMENT') {
    const cat = san(data.categorie, 20);
    const hasBenef = benef && benef !== 'ANONYME' && benef !== 'INCONNU';

    if (isFinancial) {
      // DATE-CAT-EMETTEUR-OBJET[-BENEF]-MONTANT.pdf
      const parts = [date, cat, emet, objet];
      if (hasBenef) parts.push(benef);
      parts.push(montant);
      cleanName = parts.join('-') + '.pdf';

    } else if (type === 'CONTRAT') {
      cleanName = `CONTRAT-${emet}-${objet}-${date}.pdf`;

    } else if (type === 'COURRIER') {
      cleanName = `COURRIER-${emet}-${objet}-${date}.pdf`;

    } else if (type === 'RELEVE') {
      // Période = objet (ex: MARS_2026) ou date
      cleanName = `RELEVE-${emet}-${objet}-${date}.pdf`;

    } else if (type === 'IDENTITE' || type === 'IMMIGRATION') {
      const parts = ['IDENTITE', emet, objet];
      if (hasBenef) parts.push(benef);
      parts.push(date);
      cleanName = parts.join('-') + '.pdf';

    } else if (type === 'MEDICAL') {
      const parts = ['MEDICAL', emet, objet];
      if (hasBenef) parts.push(benef);
      parts.push(date);
      cleanName = parts.join('-') + '.pdf';

    } else {
      // ADMIN générique
      cleanName = `ADMIN-${emet}-${objet}-${date}.pdf`;
    }
  }

  // Nettoyage final du nom généré (ou fourni par Gemini)
  cleanName = cleanName
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9._-]/g, '_')
    .replace(/_{2,}/g, '_')
    .replace(/^_+|_+$/g, '')
    .toUpperCase()
    .substring(0, 120);

  // ── _isFiscal : COMPTABLE requis + catégorie fiscale ───────
  const FISCAL_CATEGORIES = ['PRO','AUTONOME','MAISON_BUREAU','PRIV_SANTE','PRIV_AUTO','MIXTE'];
  const catFiscal = FISCAL_CATEGORIES.includes((data.categorie||'').toUpperCase());
  // Un document ADMINISTRATIF ne peut jamais être fiscal
  const isFiscal = famille === 'COMPTABLE' && catFiscal;

  return {
    json: {
      ...data,
      type_document:   type,
      famille_document: famille,
      est_financier:   isFinancial,
      est_fiscal_ai:   data.est_fiscal_ai === true,
      clean_filename:  cleanName,
      beneficiaire:    benef,
      montant_ttc:     Math.round(ttc * 100) / 100,
      date_journal:    date,
      _isFiscal:       isFiscal
    }
  };
});

/**
 * ROUTEUR FISCAL V10 - GED SENTINELLE
 * Triple-signal: famille_document + catégorie + est_fiscal_ai
 * + _fiscalConfidence + _annee_fiscale + _est_fiscal_label
 */
const input = $input.first().json;

function deaccent(str) {
  return (str || '').toUpperCase()
    .replace(/[''`']/g, '').replace(/[-–—]/g, '_')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^A-Z0-9]/g, '_').replace(/_{2,}/g, '_').replace(/^_+|_+$/g, '');
}

let emetteur     = deaccent(input.emetteur     || 'INCONNU');
let beneficiaire = deaccent(input.beneficiaire || 'ANONYME');
let categorie    = (input.categorie || 'PRIV_VIE').toUpperCase();
let montant_ttc  = parseFloat(input.montant_ttc) || 0;

// ── Famille document ────────────────────────────────
const COMPTABLE_TYPES = ['FACTURE', 'RECU', 'RELEVE'];
const rawFamille = (input.famille_document || '').toUpperCase();
const famille = rawFamille === 'COMPTABLE' ? 'COMPTABLE'
              : rawFamille === 'ADMINISTRATIF' ? 'ADMINISTRATIF'
              : COMPTABLE_TYPES.includes((input.type_document||'').toUpperCase()) ? 'COMPTABLE' : 'ADMINISTRATIF';

// ── Signal 1 — Catégorie fiscale ────────────────────
const FISCAL_CATEGORIES = ['PRO','AUTONOME','MAISON_BUREAU','PRIV_SANTE','PRIV_AUTO','MIXTE'];
const sigCat = FISCAL_CATEGORIES.includes(categorie);

// ── Signal 2 — Décision IA explicite ────────────────
const sigAi = input.est_fiscal_ai === true;

// ── Signal 3 — Document COMPTABLE ───────────────────
const sigComptable = famille === 'COMPTABLE';

// ── Décision finale _isFiscal ───────────────────────
// Règle : un document ne peut être fiscal que si COMPTABLE + catégorie fiscale
// (la catégorie reste le signal maître; est_fiscal_ai est un signal de validation croisée)
const isFiscal = sigComptable && sigCat;

// ── Confidence sur la décision fiscale ──────────────
let _fiscalConfidence;
if (!sigComptable) {
  // ADMINISTRATIF → jamais fiscal, pas de doute possible
  _fiscalConfidence = 'HAUTE';
} else if (sigCat && sigAi) {
  _fiscalConfidence = 'HAUTE';
} else if (sigCat && !sigAi) {
  // Catégorie dit fiscal mais IA ne confirme pas → MOYENNE, doit être validé
  _fiscalConfidence = 'MOYENNE';
} else if (!sigCat && sigAi) {
  // IA dit fiscal mais catégorie ne concorde pas → BASSE, erreur probable de classification
  _fiscalConfidence = 'BASSE';
} else {
  // Les deux disent non-fiscal → confiance haute sur "non fiscal"
  _fiscalConfidence = 'HAUTE';
}

// ── Note fiscale ────────────────────────────────────
let note_fiscale = '';
if (categorie === 'AUTONOME')          note_fiscale = 'DÉDUCTIBLE 100% (CTI/RTI)';
else if (categorie === 'PRO')           note_fiscale = 'REMBOURSABLE EMPLOYEUR';
else if (categorie === 'MAISON_BUREAU') note_fiscale = 'PRORATA BUREAU DOMICILE (ligne 9270)';
else if (categorie === 'PRIV_SANTE')   note_fiscale = 'CRÉDIT FRAIS MÉDICAUX (ligne 381)';
else if (categorie === 'PRIV_AUTO')    note_fiscale = 'FRAIS VÉHICULE — vérifier usage mixte';
else if (input.flag_mixte)             note_fiscale = '⚠️ À VENTILER (MARCHAND GÉNÉRALISTE)';

let cleanName = (input.clean_filename || 'DOCUMENT').toString();
cleanName = cleanName
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-zA-Z0-9._-]/g, '_').replace(/_{2,}/g, '_').replace(/^_+|_+$/g, '')
  .toUpperCase();

const ID_PARENT_IMPOTS  = $env.GED_IMPOTS_PARENT_ID;
const ID_PARENT_ARCHIVE = $env.GED_ARCHIVE_FOLDER_ID;

let fiscalYear = new Date().getFullYear();
try { if (input.date) fiscalYear = new Date(input.date).getFullYear(); } catch(e) {}

const targetFolderName = isFiscal ? `Impôts ${fiscalYear}` : '_GED_ARCHIVE';

// _needsValidation étendu : aussi si divergence entre signaux fiscaux
const signalsDiverge = sigComptable && (sigCat !== sigAi);
const _needsValidation = input.flag_mixte === true
                      || (input.confiance || '').toUpperCase() === 'BASSE'
                      || (_fiscalConfidence !== 'HAUTE' && signalsDiverge);

return [{
  json: {
    ...input,
    date:                input.date || new Date().toISOString().split('T')[0],
    emetteur:            emetteur,
    famille_document:    famille,
    categorie:           categorie,
    sous_categorie:      (input.sous_categorie || 'DIVERS').toUpperCase(),
    beneficiaire:        beneficiaire,
    montant_ttc:         Number(montant_ttc.toFixed(2)),
    note_fiscale:        note_fiscale,
    clean_filename:      cleanName,
    _isFiscal:           isFiscal,
    _fiscalConfidence:   _fiscalConfidence,
    _sigCat:             sigCat,
    _sigAi:              sigAi,
    _sigComptable:       sigComptable,
    _targetFolderName:   targetFolderName,
    _impotsParentId:     ID_PARENT_IMPOTS,
    _archiveFolderId:    ID_PARENT_ARCHIVE,
    _needsValidation:    _needsValidation,
    _fiscalYear:         fiscalYear,
    dossier_destination: isFiscal ? 'FISCAL' : 'ARCHIVE',
    _annee_fiscale:      String(fiscalYear),
    _est_fiscal_label:   isFiscal ? 'TRUE' : 'FALSE'
  }
}];

// PRÉPARER STAGING — Structure Miroir 30 colonnes v5
// + Famille_Document (col Y) + Fiscal_Confidence (col Z)
const d   = $input.first().json;
const now = $now.setZone('America/Toronto');

const ttc       = parseFloat(d.montant_ttc) || 0;
const flagMixte = d.flag_mixte === true;
const ratioPct  = flagMixte ? (parseFloat(d.ratio_pro_pct) || 0) : 0;
const pro        = flagMixte ? parseFloat((ttc * ratioPct).toFixed(2)) : 0;
const perso      = flagMixte ? parseFloat((ttc - pro).toFixed(2)) : 0;
const fiscalYear = (() => {
  try { const y = new Date(d.date || '').getFullYear(); return y > 2000 ? y : now.year; }
  catch(e) { return now.year; }
})();

// famille_document : valider ou inférer
const COMPTABLE_TYPES = ['FACTURE', 'RECU', 'RELEVE'];
const rawFamille = (d.famille_document || '').toUpperCase();
const famille = rawFamille === 'COMPTABLE' ? 'COMPTABLE'
              : rawFamille === 'ADMINISTRATIF' ? 'ADMINISTRATIF'
              : COMPTABLE_TYPES.includes((d.type_document||'').toUpperCase()) ? 'COMPTABLE' : 'ADMINISTRATIF';

return [{ json: {
  // ── Miroir 1→28 ──────────────────────────────────────────
  Date:                 d.date                                    || now.toISODate(),
  Emetteur:             String(d.emetteur                         || 'INCONNU'),
  Beneficiaire:         String(d.beneficiaire                     || 'ANONYME'),
  Type_Document:        String(d.type_document                    || 'ADMIN'),
  Objet:                String(d.objet || d.sous_categorie        || ''),
  Lien_Drive:           String(d._originalUrl                     || ''),
  Montant_TTC:          ttc,
  Categorie:            String(d.categorie                        || ''),
  Sous_Categorie:       String(d.sous_categorie                   || ''),
  Annee_Fiscale:        fiscalYear,
  Est_Fiscal:           d._isFiscal === true,
  Flag_Mixte:           flagMixte,
  Ratio_Pro_Pct:        ratioPct,
  Montant_Pro_Estime:   pro,
  Montant_Perso_Estime: perso,
  Est_Valide_Mixte:     false,
  Montant_Pro_Valide:   0,
  Confiance:            String(d.confiance                        || 'BASSE'),
  Raison_Doute:         String(d.raison_doute                     || ''),
  Mention_Manuscrite:   String(d.mention_manuscrite               || ''),
  Est_Financier:        d.est_financier !== false,
  Source:               String(d._source                          || 'INCONNUE'),
  File_Name:            String(d._fileName                        || d.clean_filename || ''),
  Empreinte:            String(d._empreinte                       || ''),
  Hash:                 String(d._hash                            || ''),
  Gmail_Id:             String(d._gmailId                         || ''),
  File_Id:              String(d._fileId                          || ''),
  Date_Traitement:      now.toISO(),
  // ── Cols 29-30 (Y-Z) ─────────────────────────────────────
  Famille_Document:     famille,
  Fiscal_Confidence:    String(d._fiscalConfidence                || 'BASSE')
}}];

// APPROBATION AUTOMATIQUE — Structure Miroir 30 colonnes v5
// + Famille_Document (col Y) + Fiscal_Confidence (col Z)
const d      = $input.first().json;
const source = d._source || $('⚙️ Normaliser Source').first().json.source || 'INCONNUE';
const now    = $now.setZone('America/Toronto');

let empreinte = '';
try { empreinte = $('🧬 WD — Calculer Empreinte').first().json._empreinte || ''; } catch(e) {}
let hash = '';
try { hash = $('🔐 WD L0 — Calculer Hash (SHA-256)').first().json._hash || ''; } catch(e) {}

const ttc       = parseFloat(d.montant_ttc) || 0;
const flagMixte = d.flag_mixte === true;
const ratioPct  = flagMixte ? (parseFloat(d.ratio_pro_pct) || 0) : 0;
const pro        = flagMixte ? parseFloat((ttc * ratioPct).toFixed(2)) : 0;
const perso      = flagMixte ? parseFloat((ttc - pro).toFixed(2)) : 0;
const fiscalYear = (() => {
  try { const y = new Date(d.date || '').getFullYear(); return y > 2000 ? y : now.year; }
  catch(e) { return now.year; }
})();

// famille_document : valider ou inférer
const COMPTABLE_TYPES = ['FACTURE', 'RECU', 'RELEVE'];
const rawFamille = (d.famille_document || '').toUpperCase();
const famille = rawFamille === 'COMPTABLE' ? 'COMPTABLE'
              : rawFamille === 'ADMINISTRATIF' ? 'ADMINISTRATIF'
              : COMPTABLE_TYPES.includes((d.type_document||'').toUpperCase()) ? 'COMPTABLE' : 'ADMINISTRATIF';

// ── Routage annuel fiscal/comptable ─────────────────────────────────────────
let _docYear = null;
try {
  const y = new Date(d.date || '').getFullYear();
  if (y > 2000 && y <= now.year + 1) _docYear = y;
} catch(e) {}

const _anneeManquante = _docYear === null;
if (_anneeManquante) {
  console.warn('Année document non détectable — Action_Requise sera ANNÉE_MANQUANTE');
}

const _targetFolderName = d._isFiscal
  ? `Impôts ${_docYear || now.year}`
  : `Comptabilité ${_docYear || now.year}`;

// ✅ Correction : utiliser $env au lieu de process.env
const _impotsParentId = $env.GED_IMPOTS_PARENT_ID || '';
const _comptaParentId = $env.GED_COMPTA_PARENT_ID || '';

const _sheetRow = {
  Date:                 d.date                                                 || now.toISODate(),
  Emetteur:             String(d.emetteur                                      || 'INCONNU'),
  Beneficiaire:         String(d.beneficiaire                                  || 'ANONYME'),
  Type_Document:        String(d.type_document                                 || 'ADMIN'),
  Objet:                String((d.objet && d.objet !== '') ? d.objet.toUpperCase() : (d.sous_categorie || 'DIVERS')),
  Lien_Drive:           '',
  Montant_TTC:          ttc,
  Categorie:            String(d.categorie                                     || 'INCONNUE'),
  Sous_Categorie:       String(d.sous_categorie                                || ''),
  Annee_Fiscale:        fiscalYear,
  Est_Fiscal:           d._isFiscal === true,
  Flag_Mixte:           flagMixte,
  Ratio_Pro_Pct:        ratioPct,
  Montant_Pro_Estime:   pro,
  Montant_Perso_Estime: perso,
  Est_Valide_Mixte:     false,
  Montant_Pro_Valide:   0,
  Confiance:            String(d.confiance                                     || 'BASSE'),
  Raison_Doute:         String(d.raison_doute                                  || ''),
  Mention_Manuscrite:   String(d.mention_manuscrite                            || ''),
  Est_Financier:        d.est_financier !== false,
  Source:               String(source),
  File_Name:            String(d._fileName                                     || ''),
  Empreinte:            empreinte,
  Hash:                 hash,
  Gmail_Id:             String(d._gmailId                                      || ''),
  File_Id:              String(d._fileId                                       || ''),
  Date_Traitement:      now.toISO(),
  Famille_Document:     famille,
  Fiscal_Confidence:    String(d._fiscalConfidence                             || 'BASSE')
};

return [{ json: {
  ...d,
  _source:           source,
  _empreinte:        empreinte,
  _hash:             hash,
  _validationMethod: 'AUTO_IA',
  _finalFileName:    d.clean_filename || 'DOCUMENT_SANS_NOM.pdf',
  _sheetRow
}}];

// ══════════════════════════════════════════════════
// RÉSOUDRE DOSSIER CIBLE v2
// Fiscal   → chercher/créer 'Impôts YYYY'        sous GED_IMPOTS_PARENT_ID
// Comptable → chercher/créer 'Comptabilité YYYY' sous GED_COMPTA_PARENT_ID
// Année manquante → Action_Requise = ANNÉE_MANQUANTE, pas d'archivage
// ══════════════════════════════════════════════════
const d = $input.first().json;

// Cas année manquante → bloquer l'archivage
if (d._anneeManquante) {
  return [{ json: {
    ...d,
    _resolveFolder: false,
    _resolvedFolderId: null,
    _anneeManquante: true,
    Action_Requise: 'ANNÉE_MANQUANTE'
  }}];
}

// Dans tous les cas (fiscal OU comptable) → déclencher la recherche du sous-dossier annuel
// Le nœud 'Search files and folders' utilisera _targetFolderName et le bon parent
return [{ json: {
  ...d,
  _resolveFolder: true,
  _resolvedFolderId: null
}}];

// ══════════════════════════════════════════════════
// RÉSOUDRE ID FINAL v2
// Cas 1: dossier trouvé via Search → files[0].id
// Cas 2: dossier créé → id direct
// Fallback: parent Comptabilité ou Impôts selon _isFiscal
// ══════════════════════════════════════════════════
const inputData = $input.first().json;
const approData = $('✅ Approbation Automatique').first().json;

// Cas 1: vient de Search files (files[])
let targetFolderId = inputData.files?.[0]?.id;

// Cas 2: vient de Créer dossier (id direct)
if (!targetFolderId) targetFolderId = inputData.id;

// Fallback : pointer sur le dossier parent (Impôts ou Comptabilité)
if (!targetFolderId) {
  targetFolderId = approData._isFiscal
    ? $env.GED_IMPOTS_PARENT_ID
    : $env.GED_COMPTA_PARENT_ID;
  console.warn('Fallback dossier parent — sous-dossier annuel introuvable');
}

return [{
  json: {
    ...approData,
    _resolvedFolderId: targetFolderId
  }
}];

// INJECTER LIEN DRIVE — patch Lien_Drive + File_Id + Empreinte + Hash dans _sheetRow v3
const d           = $('✅ Approbation Automatique').first().json;
const driveResult = $('☁️ Archiver Fichier Renommé').first().json;
const driveLink   = driveResult.webViewLink || driveResult.webContentLink || '';
const archivedId  = driveResult.id || d._sheetRow.File_Id || '';  // ← ID du fichier archivé (source de vérité)
const fiscalYear  = $('🗺️ Router Fiscal').first().json._fiscalYear || new Date().getFullYear();

let empreinte = '';
try { empreinte = $('🧬 WD — Calculer Empreinte').first().json._empreinte || ''; } catch(e) {}
let hash = '';
try { hash = $('🔐 WD L0 — Calculer Hash (SHA-256)').first().json._hash || ''; } catch(e) {}

// Patch sur la row miroir — File_Id = ID archivé final (pas l'ID _Scanner original)
const row = {
  ...d._sheetRow,
  Lien_Drive: driveLink,
  File_Id:    archivedId,
  Empreinte:  empreinte,
  Hash:       hash
};

return [{ json: {
  ...d,
  _fileId:     archivedId,
  _empreinte:  empreinte,
  _hash:       hash,
  _sheetRow:   row,
  _driveLink:  driveLink,
  _fiscalYear: fiscalYear
}}];

