// ══════════════════════════════════════════════════
// TROUVER PJ — Validation & passthrough (v3)
// _attachId déjà connu depuis 🔍 Compter & Lister PJ
// Ce nœud valide et enrichit — ne re-parse plus le payload
// ══════════════════════════════════════════════════
const msg  = $input.first().json;
const meta = $('⚙️ Normaliser Source').first().json;

// Cas email sans PJ (flag de Compter & Lister PJ)
if (msg._noAttachment || meta._attachTotal === 0) {
  console.warn('Trouver PJ: email sans PJ — passage fallback');
  return [{
    json: {
      ...meta,
      _gmailId:        meta.gmailId || msg.id || '',
      _attachId:       null,
      _partId:         null,
      fileName:        meta.fileName || `email_${msg.id || Date.now()}.pdf`,
      mimeType:        'application/pdf',
      _attachSize:     0,
      _allAttachments: 0,
      _noAttachment:   true
    }
  }];
}

// _attachId déjà résolu — juste enrichir et passer
return [{
  json: {
    ...meta,
    _gmailId:        meta.gmailId || msg.id || '',
    _attachId:       meta._attachId,
    _partId:         msg._partId || '',
    fileName:        meta.fileName,
    mimeType:        meta.mimeType || 'application/pdf',
    _attachSize:     msg._attachSize || 0,
    _allAttachments: meta._attachTotal || 1,
    _attachIndex:    meta._attachIndex || 1
  }
}];

// ══════════════════════════════════════════════════
// DÉCODER PJ BASE64 → BINAIRE (v2)
// Robuste : fallback si data absent
// ══════════════════════════════════════════════════
const apiResp = $input.first().json;
const meta    = $('🗂️ Gmail — Trouver PJ').first().json;

// Cas email sans PJ — passer directement
if (meta._noAttachment) {
  console.warn('Email sans PJ — passage en fallback');
  return [{
    json: { ...meta, _decodeError: true },
    binary: {}
  }];
}

const base64url = apiResp.data;
if (!base64url) {
  console.warn('Réponse API Gmail vide — champ data absent:', Object.keys(apiResp).join(','));
  return [{
    json: {
      ...meta,
      _decodeError:   true,
      _decodeWarning: 'Champ data absent dans réponse Gmail API'
    },
    binary: {}
  }];
}

// Convertir base64url → base64 standard
const base64std = base64url.replace(/-/g, '+').replace(/_/g, '/');

return [{
  json: {
    ...meta,
    fileName: meta.fileName,
    mimeType: meta.mimeType
  },
  binary: {
    data: {
      data:          base64std,
      mimeType:      meta.mimeType || 'application/pdf',
      fileName:      meta.fileName || 'facture.pdf',
      fileSize:      apiResp.size  || 0,
      fileExtension: (meta.fileName || 'pdf').split('.').pop()
    }
  }
}];

// ══════════════════════════════════════════════════
// WATCHDOG L1 — Analyser résultat Staging (fileId)
// Structure miroir 28 cols: File_Id = col 27 (index 26, 0-based)
// ══════════════════════════════════════════════════
const meta   = $('⚙️ Normaliser Source').first().json;
const fileId = meta.fileId || '';

let l1Hit = null;
try {
  const resp = $('🐕 WD L1 — fileId dans Staging').first().json;
  const rows = resp.values || [];

  const FILE_ID_COL = 26; // col 27 (File_Id) — 0-based

  const matchRow = rows.find((row, i) => i > 0 && row[FILE_ID_COL] === fileId);

  if (matchRow) {
    const statut = matchRow.slice().reverse().find(v => v && v.trim() !== '') || 'INCONNU';
    l1Hit = {
      fileId,
      processedAt: matchRow[27] || 'inconnu', // Date_Traitement col 28
      statut: statut
    };
  }
} catch(e) {
  console.log('WD L1 parse error:', e.message);
}

const isDoublon = !!l1Hit && l1Hit.statut !== 'EN_ATTENTE';

return [{
  json: {
    ...meta,
    _isDoublon:      isDoublon,
    _stagingHit:     l1Hit,
    _stagingStatut:  l1Hit ? l1Hit.statut : null
  }
}];

