// Liste des catégories
const categories = [
  "AUTONOME", "PRO", "MAISON_BUREAU", "PRIV_SANTE",
  "PRIV_AUTO", "PRIV_VIE", "MIXTE", "IGNORER"
];

// Créer les boutons
const buttons = categories.map(cat => ({
  text: cat,
  callback_data: cat
}));

// Grouper les boutons par 2
const keyboard = [];
for (let i = 0; i < buttons.length; i += 2) {
  keyboard.push(buttons.slice(i, i + 2));
}

// Préparer la structure pour Telegram
const reply_markup = { inline_keyboard: keyboard };

// Ajouter la structure à l'item
return [{
  json: {
    ...$input.first().json,
    reply_markup: reply_markup
  }
}];

// ══════════════════════════════════════════════════
// RETOUR BATCH — Expose les données pour Collecter Résultats
// Exécuté uniquement en mode BATCH (Mode Silencieux ?4 FALSE)
// ══════════════════════════════════════════════════════════════════════════════
// DISTINCTION CLARA : famille_document + type_document + est_fiscal
// JET (Contrats, admin, docs légaux) → famille_document = ADMINISTRATIF
// Comptable (Factures, relevés) → famille_document = COMPTABLE + est_fiscal = false
// Fiscal (Comptable + catégorie fiscale) → famille_document = COMPTABLE + est_fiscal = true
// ══════════════════════════════════════════════════════════════════════════════

const d = $('🔗 Injecter Lien Drive').first().json;
return [{ json: {
  // ── Identité du document ──────────────────────────────────────────────────
  date:           d.date           || '',
  emetteur:       d.emetteur       || '',
  objet:          d.objet          || '',
  beneficiaire:   d.beneficiaire   || '',

  // ── Classification et famille (DISTINCTION CLARA) ────────────────────────
  type_document:  d.type_document   || 'ADMIN',              // FACTURE, CONTRAT, COURRIER, ADMIN...
  famille_document: d.famille_document || 'ADMINISTRATIF',   // COMPTABLE ou ADMINISTRATIF
  est_fiscal:     d._isFiscal       === true ? true : false, // true=COMPTABLE+fiscal, false=comptable ou JET
  categorie:      d.categorie      || '',
  sous_categorie: d.sous_categorie || '',

  // ── Confiance et notes ────────────────────────────────────────────────────
  confiance:      d.confiance      || '',
  fiscal_confidence: d._fiscalConfidence || '',              // HAUTE/MOYENNE/BASSE sur décision fiscal
  raison_doute:   d.raison_doute   || d.note_fiscale || '',

  // ── Financier ─────────────────────────────────────────────────────────────
  montant_ttc:    d.montant_ttc    || 0,
  est_financier:  d.est_financier  || false,
  flag_mixte:     d.flag_mixte      || false,

  // ── Fichier et métadonnées ────────────────────────────────────────────────
  clean_filename: d.clean_filename || d._finalFileName || '',
  _driveLink:     d._driveLink     || '',
  _hash:          d._hash          || '',
  _empreinte:     d._empreinte     || '',

  // ── Flags internes ────────────────────────────────────────────────────────
  _isFiscal:      d._isFiscal      || false,
  _hashDoublon:   d._hashDoublon   || false,
  _isDoublon:     d._isDoublon     || false,
  _fileId:        d._fileId        || d.fileId   || '',
  _fileName:      d._fileName      || d.fileName || '',
  _source:        'BATCH'
}}];

// Retour minimal pour BATCH en cas de doublon détecté
const meta = $('⚙️ Normaliser Source').first().json;
return [{ json: {
  _fileId:      meta.fileId   || '',
  _fileName:    meta.fileName || '',
  _source:      'BATCH',
  _isDoublon:   true,
  _isFiscal:    false,
  _hashDoublon: false,
  date: '', emetteur: '', objet: '', beneficiaire: '',
  montant_ttc: 0, categorie: '', sous_categorie: '',
  confiance: '', raison_doute: 'DOUBLON', clean_filename: '',
  _driveLink: '', _hash: '', _empreinte: ''
}}];

// ══════════════════════════════════════════════════
// COMPTER & LISTER PJ — Pré-processing Gmail multi-PJ (v1)
// Retourne 1 item par PJ éligible
// Chaque item porte _attachId, _attachIndex, _attachTotal
// Si 0 PJ → 1 item placeholder _noAttachment
// ══════════════════════════════════════════════════
const msg = $input.first().json;

// ── Helper: extraire email brut ──
function extractEmail(raw) {
  if (!raw) return '';
  const angle = raw.match(/<([^>]+)>/);
  if (angle) return angle[1].trim().toLowerCase();
  const plain = raw.match(/([^\s<>"',;]+@[^\s<>"',;]+)/);
  return plain ? plain[1].trim().toLowerCase() : raw.trim().toLowerCase();
}

// ── Validation alias +scan (double-check ici aussi) ──
const headers  = msg.payload?.headers || [];
const ALIAS    = ($env.GED_GMAIL_ALIAS || 'debourouba+scan@gmail.com').toLowerCase();
const toRaw    = headers.find(h => h.name?.toLowerCase() === 'to')?.value || '';
const delRaw   = headers.find(h => h.name?.toLowerCase() === 'delivered-to')?.value || '';
const toEmail  = extractEmail(toRaw);
const delEmail = extractEmail(delRaw);

const isTargeted = toEmail.includes(ALIAS) || delEmail.includes(ALIAS);
if (!isTargeted) {
  console.warn(`Compter PJ: email ignoré — alias non détecté. To="${toRaw}" Del="${delRaw}"`);
  return []; // stoppe le flux pour cet email
}

// ── MIME types acceptés ──
const ELIGIBLE = ['application/pdf','image/jpeg','image/jpg',
                  'image/png','image/heic','image/webp','image/tiff'];

// ── Traversée récursive des parts ──
function findAttachments(parts, results = []) {
  if (!Array.isArray(parts)) return results;
  for (const part of parts) {
    const hasAttachId = !!part.body?.attachmentId;
    const hasFilename = !!(part.filename && part.filename.trim().length > 0);
    const isEligible  = ELIGIBLE.some(m => (part.mimeType || '').toLowerCase().includes(
                          m.split('/')[1]
                        ));
    if (hasAttachId && hasFilename && isEligible) {
      results.push({
        attachmentId: part.body.attachmentId,
        filename:     part.filename.trim(),
        mimeType:     part.mimeType,
        size:         part.body.size || 0,
        partId:       part.partId || ''
      });
    }
    if (Array.isArray(part.parts)) findAttachments(part.parts, results);
  }
  return results;
}

const attachments = findAttachments(msg.payload?.parts || []);
const total       = attachments.length;

// Extraire sujet et expéditeur pour enrichissement
const hFrom    = headers.find(h => h.name?.toLowerCase() === 'from');
const hSubject = headers.find(h => h.name?.toLowerCase() === 'subject');
const fromAddr = hFrom?.value    || '';
const subject  = hSubject?.value || '';

console.log(`📎 Gmail ${msg.id} — PJ détectées: ${total} | Alias OK: ${isTargeted}`);

// ── Cas 0 PJ éligible ─────────────────────────────
if (total === 0) {
  return [{
    json: {
      // Champs isGmail detection pour Normaliser Source
      threadId:     msg.threadId,
      historyId:    msg.historyId,
      id:           msg.id,
      labels:       msg.labelIds || [],
      from:         fromAddr,
      subject:      subject,
      payload:      msg.payload, // garder pour isValidScanTarget dans Normaliser Source
      // Métadonnées PJ
      _attachId:    null,
      _attachIndex: 1,
      _attachTotal: 0,
      _noAttachment: true,
      fileName:     `email_${msg.id}.pdf`,
      mimeType:     'application/pdf'
    }
  }];
}

// ── Cas N PJ → N items ────────────────────────────
return attachments.map((att, i) => ({
  json: {
    // Champs isGmail detection
    threadId:  msg.threadId,
    historyId: msg.historyId,
    id:        msg.id,
    labels:    msg.labelIds || [],
    from:      fromAddr,
    subject:   subject,
    payload:   msg.payload,
    // Métadonnées PJ spécifiques
    _attachId:    att.attachmentId,
    _attachIndex: i + 1,
    _attachTotal: total,
    fileName:     att.filename,
    mimeType:     att.mimeType,
    _attachSize:  att.size,
    _partId:      att.partId
  }
}));

// ══════════════════════════════════════════════════════════════════════════════
// WD L0 — Calculer Hash SHA-256 + pHash (v6 — sandbox-compatible)
// ══════════════════════════════════════════════════════════════════════════════
// 
// CHANGEMENTS v5 → v6:
// • fs.writeFileSync / execSync / fs.readFileSync / fs.existsSync SUPPRIMÉS
//   (bloqués dans n8n v2 task-runner sandbox)
// • PDF pHash: fallback vers SHA-256(binary).slice(0,16) au lieu de pdftoppm
// • Garantit que _pHash n'est JAMAIS vide (si binaire présent)
// • _pHash transporté dans le json pour écriture en col C (HASH_LOCK)
//
// ══════════════════════════════════════════════════════════════════════════════

const { createHash } = require('crypto');

const item = $input.first();
const meta = $('⚙️ Normaliser Source').first().json;

// ── Récupérer le binaire ─────────────────────────────────────────────────────
// ExtractFromFile place le contenu dans item.json.data (base64 string)
// item.binary.data.data contient aussi le base64 dans certains modes
const b64 = item.json?.data
         || item.binary?.data?.data
         || '';

const fileName = meta.fileName || item.binary?.data?.fileName || 'INCONNU';

// ── SHA-256 ──────────────────────────────────────────────────────────────────
let hash = null;
let hashSource = 'FALLBACK';

try {
  if (b64 && b64.length > 10) {
    const bytes = Buffer.from(b64, 'base64');
    if (bytes.length > 0) {
      hash = createHash('sha256').update(bytes).digest('hex');
      hashSource = 'SHA256_BINARY';
    }
  }
} catch(e) {
  console.error('SHA256 error:', e.message);
}

// Fallback métadonnées si binaire absent
if (!hash) {
  const fb = Buffer.from(
    (meta.fileId || '') + '|' + (meta.fileName || '') + '|' + (meta.gmailId || ''),
    'utf8'
  );
  hash = createHash('sha256').update(fb).digest('hex');
  hashSource = 'FALLBACK_METADATA_SHA256';
  console.warn('Hash fallback (binaire absent):', fileName);
}

// ── pHash ─────────────────────────────────────────────────────────────────────
// Approche sandbox-compatible (pas de fs/execSync)
// 
// • PDF: SHA-256(binary).slice(0,16) 
//   → Ne capture pas variations perceptuelles (pdftoppm impossible)
//   → Mais identifie doublons exacts et se calcule en sandbox
// 
// • Image: SHA-256(binary).slice(0,16) 
//   → Comportement identique (cohérence)
//
// Couche 1 (SHA-256 exact) détecte déjà les duplicatas binaires exacts.
// pHash offre une 2e couche si near-duplicate détection ajoutée plus tard (Hamming).

let pHash = '';
let pHashAlgo = 'none';

try {
  if (!b64 || b64.length < 10) {
    throw new Error('Binaire absent ou trop court pour pHash');
  }

  // Détecter type fichier
  const binaryMime = item.binary?.data?.mimeType || '';
  const metaMime   = meta.mimeType || meta.fileType || '';
  const fileNameLc = fileName.toLowerCase();
  const isPdf      = binaryMime.includes('pdf')
                  || metaMime.includes('pdf')
                  || fileNameLc.endsWith('.pdf');

  // SHA-256 du binaire brut → troncaturé à 16 chars (hex)
  // Valable pour PDF et images (uniforme)
  const bytes = Buffer.from(b64, 'base64');
  if (bytes.length > 0) {
    pHash = createHash('sha256').update(bytes).digest('hex').slice(0, 16);
    pHashAlgo = isPdf ? 'sha256-raw-pdf-sandbox' : 'sha256-raw-image';

    console.log(
      `pHash calculé [${pHashAlgo}] fichier=${fileName.slice(0, 40)} ` +
      `pHash=${pHash} bytes=${bytes.length}`
    );
  }
} catch(e) {
  console.error('pHash error (non bloquant):', e.message, 'fichier:', fileName);
  // pHash reste '' — acceptable, col C sera vide mais le flux ne bloque pas
}

// ── Validation & Return ──────────────────────────────────────────────────────
if (!hash) {
  console.error('ERREUR CRITIQUE: Hash SHA-256 non calculé. Abandon.');
  throw new Error('SHA-256 hash calculation failed');
}

console.log(
  `[WD L0] hash=${hash.slice(0, 16)}... source=${hashSource} ` +
  `pHash=${pHash || '(vide)'} algo=${pHashAlgo} fichier=${fileName}`
);

return [{
  json: {
    // Préserver le contexte document
    ...item.json,

    // Hash SHA-256 (exact)
    _hash:        hash,
    _hashSource:  hashSource,

    // pHash (near-duplicate, ou fallback exact pour sandbox)
    _pHash:       pHash,
    _pHashAlgo:   pHashAlgo,

    // Métadonnées source (pour trace & journalisation)
    _fileName:    fileName,
    _fileId:      meta.fileId || null,
    _gmailId:     meta.gmailId || null,
    _source:      meta.source || 'unknown'
  },

  // Binaire préservé pour étapes suivantes (archivage, etc)
  binary: item.binary || {}
}];

// WD L0 — Préparer recherche Hash (v4 — sans $helpers)
const hashItem = $('🔐 WD L0 — Calculer Hash (SHA-256)').first();
const hash     = hashItem.json._hash || '';
const meta     = hashItem.json;

if (!hash) {
  // Hash vide → pas de doublon, passer directement
  return [{ json: { ...meta, _hash: hash, _skipHashSearch: true, _hashDoublon: false, _hashDoublonSource: null }, binary: hashItem.binary }];
}

// Passer le hash en avant pour les HTTP Request nodes
return [{ json: { ...meta, _hash: hash, _skipHashSearch: false }, binary: hashItem.binary }];

// WD L0 — Agréger résultats recherche Hash (v4)
const meta = $('🔍 WD L0 — Chercher Hash (3 sources)').first().json;
const hash = meta._hash || '';

function colContains(respJson, hash) {
  const col = (respJson?.values || [])[0] || [];
  if (!col || col.length < 2) return false;  // ← Ajouter cette ligne
  return col.slice(1).some(v => String(v).trim() === String(hash).trim());
}

let source = null;

try {
  const rComptable = $('🔎 Hash — Journal Comptable').first().json;
  console.log(`Journal Comptable col count: ${rComptable?.values?.[0]?.length || 0}`);
  if (colContains(rComptable, hash)) { source = 'JOURNAL_COMPTABLE'; }
} catch(e) { console.error('Comptable error:', e.message); }

if (!source) {
  try {
    const rGed = $('🔎 Hash — Journal GED').first().json;
    console.log(`Journal GED col count: ${rGed?.values?.[0]?.length || 0}`);
    if (colContains(rGed, hash)) { source = 'JOURNAL_GED'; }
  } catch(e) { console.error('GED error:', e.message); }
}

if (!source) {
  try {
    const rStaging = $('🔎 Hash — Staging').first().json;
    console.log(`Staging col count: ${rStaging?.values?.[0]?.length || 0}`);
    if (colContains(rStaging, hash)) { source = 'STAGING'; }
  } catch(e) { console.error('Staging error:', e.message); }
}

return [{ json: { ...meta, _hashDoublon: source !== null, _hashDoublonSource: source, _hash: hash }, binary: $input.first().binary || {} }];

// WD — Écrire Hash Lock — Préparer payload (v4 sans $helpers)
const hashData = $('🔐 WD L0 — Calculer Hash (SHA-256)').first().json;
const meta     = $('⚙️ Normaliser Source').first().json;
const now      = $now.setZone('America/Toronto').toISO();

const row = [
  hashData._hash   || '',
  now,
  '',                     // pHash — rempli après couche 2
  meta.fileName    || '',
  meta.source      || ''
];

return [{
  json: {
    ...$input.first().json,
    _lockRow:  row,
    _lockHash: hashData._hash || ''
  }
}];

// Calcul Hamming distance sur HASH_LOCK col C
// _pHash transporté depuis 🔐 WD L0 — Calculer Hash (SHA-256)
const d     = $input.first().json;
const pHash = d._pHash
              || $('🔐 WD L0 — Calculer Hash (SHA-256)').first().json._pHash
              || '';
const rows  = ($('📡 HTTP — Lire HASH_LOCK Hamming').first().json.values || []).slice(1);

const THRESHOLD = 8;

function hammingHex(a, b) {
  if (!a || !b || a.length !== b.length) return 64;
  const bigA = BigInt('0x' + a);
  const bigB = BigInt('0x' + b);
  let xor = bigA ^ bigB;
  let dist = 0;
  while (xor > 0n) { dist += Number(xor & 1n); xor >>= 1n; }
  return dist;
}

if (!pHash) {
  return [{ json: { ...d, _pHash: pHash, _pHashDoublon: false, _pHashDistance: null, _pHashMatch: null } }];
}

let bestDist = 64;
let bestRow  = null;

for (const row of rows) {
  const existing = (row[2] || '').trim();
  if (!existing || existing.length !== 16) continue;
  const dist = hammingHex(pHash, existing);
  if (dist < bestDist) { bestDist = dist; bestRow = row; }
}

const isDoublon = bestDist <= THRESHOLD;

return [{
  json: {
    ...d,
    _pHash:         pHash,
    _pHashDoublon:  isDoublon,
    _pHashDistance: bestDist,
    _pHashMatch:    isDoublon ? (bestRow?.[3] || null) : null
  }
}];

// Prépare hash + pHash pour update dans HASH_LOCK
const d     = $input.first().json;
const hashNode = $('🔐 WD L0 — Calculer Hash (SHA-256)').first().json;
const hash  = d._lockHash || hashNode._hash || '';
const pHash = d._pHash    || hashNode._pHash || '';

console.log(`Update pHash: hash=${hash.slice(0,8)}... pHash=${pHash}`);

return [{
  json: { ...d, _updateHash: hash, _updatePHash: pHash }
}];

// Trouver la ligne du hash dans HASH_LOCK et construire range PUT
const d       = $('📝 Update pHash → _HASH_LOCK').first().json;
const hash    = d._updateHash  || '';
const pHash   = d._updatePHash || '';
const rows    = $('📡 HTTP — Lire Hash Lock col A').first().json.values || [];

let targetRow = -1;
for (let i = rows.length - 1; i >= 1; i--) {
  if ((rows[i][0] || '').trim() === hash.trim()) {
    targetRow = i + 1; // 1-indexed Sheets
    break;
  }
}

if (targetRow === -1 || !pHash) {
  console.warn(`Update pHash skip: targetRow=${targetRow}, pHash="${pHash}", hash="${hash}"`);
  return [{ json: { ...d, _pHashRange: '', _pHashValue: pHash, _pHashUpdateSkipped: true } }];
}

// Range NON encodé — l'URL du HTTP PUT l'encodera via encodeURIComponent
return [{
  json: {
    ...d,
    _pHashRange:         `HASH_LOCK!C${targetRow}`,
    _pHashValue:         pHash,
    _pHashUpdateSkipped: false
  }
}];

// Restaurer le binaire depuis le noeud Hash (dernier à l'avoir conservé)
// Nécessaire car les HTTP Request nodes de la chaîne pHash écrasent le binary
const current = $input.first().json;

let binaryData = null;

// Tentative 1 : depuis WD L0 Calculer Hash (source fiable)
try {
  const hashNode = $('🔐 WD L0 — Calculer Hash (SHA-256)').first();
  if (hashNode.binary && Object.keys(hashNode.binary).length > 0) {
    binaryData = hashNode.binary;
  }
} catch(e) {}

// Tentative 2 : depuis Extract from File
if (!binaryData) {
  try {
    const extractNode = $('Extract from File').first();
    if (extractNode.binary && Object.keys(extractNode.binary).length > 0) {
      binaryData = extractNode.binary;
    }
  } catch(e) {}
}

if (!binaryData) {
  throw new Error('Restaurer Binaire: impossible de récupérer le binaire depuis les noeuds amont');
}

return [{
  json: current,
  binary: binaryData
}];

const d = $input.first().json;

const message = `⚠️ *Doublon pHash détecté* — ignoré

📄 *Fichier:* ${d._fileName || 'inconnu'}
🔢 *pHash:* \`${d._pHash || ''}\`
📏 *Distance Hamming:* ${d._pHashDistance ?? '?'}/64
🔗 *Doublon probable:* ${d._pHashMatch || 'inconnu'}`;

return [{ json: { ...d, _telegramMessage: message } }];
